  function greeting(){const d=NOW(),mm=String(d.getMonth()+1).padStart(2,'0'),dd=String(d.getDate()).padStart(2,'0');let g=SOL[mm+'-'+dd];if(!g){const l=lunar(d);if(l)g=LUN[l[0]+'/'+l[1]]}return g||null}
