  /* ====== Bảng nhỏ bật/tắt của học viên (nút hiệu ứng) ====== */
  const pop=document.createElement('div');pop.id='mua-pop';pop.hidden=true;
  pop.innerHTML='<button type="button" role="switch" data-k="fx"><span>Hiệu ứng động</span><i></i></button>';
  document.body.appendChild(pop);
  function syncPop(){pop.querySelector('[data-k=fx]').setAttribute('aria-checked',String(!fxOff))}
  function placePop(){const r=fxBtn.getBoundingClientRect();pop.style.top=(r.bottom+8)+'px';pop.style.right=Math.max(8,innerWidth-r.right-4)+'px'}
  if(fxBtn){fxBtn.setAttribute('aria-pressed',String(!fxOff));
    fxBtn.onclick=e=>{e.stopPropagation();fxOff=!fxOff;LS('gy_fx_off',fxOff?'1':'0');fxBtn.setAttribute('aria-pressed',String(!fxOff));fxBtn.title=fxOff?'Bật hiệu ứng động':'Tắt hiệu ứng động';apply(setting)}}
